Es ez?const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;
const tensor_mod = @import("runtime/tensor.zig");
const types_mod = @import("runtime/types.zig");
const rsf_mod = @import("arch/rsf.zig");
const mgt_mod = @import("arch/mgt.zig");
const ssi_mod = @import("arch/ssi.zig");
const ranker_mod = @import("arch/ranker.zig");
const sfd_mod = @import("training/sfd.zig");
const Tensor = tensor_mod.Tensor;
const PRNG = types_mod.PRNG;
const RSF = rsf_mod.RSF;
const MGT = mgt_mod.MGT;
const SSI = ssi_mod.SSI;
const Ranker = ranker_mod.Ranker;
const SFD = sfd_mod.SFD;
const SFDConfig = sfd_mod.SFDConfig;
const SFDTensor = sfd_mod.Tensor;

pub const JAIDEConfig = struct {
    hidden_dim: usize = 512,
    num_layers: usize = 12,
    num_heads: usize = 8,
    fractal_depth: usize = 4,
    vocab_size: usize = 32000,
    max_seq_len: usize = 2048,
    learning_rate: f32 = 1e4,
    fisher_decay: f32 = 0.999,
    surprise_threshold: f32 = 0.1,
    momentum: f32 = 0.9,
    ssi_max_height: usize = 6,
    ranker_num_ngrams: usize = 64,
    ranker_num_hash_funcs: usize = 16,
    ranker_seed: u64 = 0xDEADBEEF,
    dropout_rate: f32 = 0.1,
    temperature: f32 = 0.8,
    clip_threshold: f32 = 1.0,
    warmup_steps: usize = 100,
};

pub const JAIDEModel = struct {
    config: JAIDEConfig,
    tokenizer: MGT,
    processor: RSF,
    index: SSI,
    ranker: Ranker,
    sfd_optimizer: SFD,
    embedding_table: Tensor,
    output_projection: Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, config: JAIDEConfig) !JAIDEModel {
        const half_dim = config.hidden_dim;
        const rsf_dim = half_dim;

        var processor = try RSF.init(allocator, rsf_dim, config.num_layers);
        errdefer processor.deinit();

        const vocab: []const []const u8 = &.{};
        const anchors: []const []const u8 = &.{};
        var tokenizer = try MGT.init(allocator, vocab, anchors);
        errdefer tokenizer.deinit();

        var index = SSI.init(allocator);
        errdefer index.deinit();

        var ranker = try Ranker.init(allocator, config.ranker_num_ngrams, config.ranker_num_hash_funcs, config.ranker_seed);
        errdefer ranker.deinit();

        const total_params = config.vocab_size  config.hidden_dim + config.hidden_dim  config.vocab_size;
        var sfd_optimizer = try SFD.initWithConfig(allocator, total_params, .{
            .beta1 = config.momentum,
            .beta2 = config.fisher_decay,
            .eps = 1e8,
            .clip_threshold = config.clip_threshold,
            .fisher_max = 1e6,
            .warmup_steps = config.warmup_steps,
        });
        errdefer sfd_optimizer.deinit();

        const embed_shape = [_]usize{ config.vocab_size, config.hidden_dim };
        const xavier_bound = math.sqrt(6.0 / @as(f32, @floatFromInt(config.vocab_size + config.hidden_dim)));
        var embedding_table = try Tensor.randomUniform(allocator, &embed_shape, xavier_bound, xavier_bound, 42);
        errdefer embedding_table.deinit();
"
        const proj_shape = [_]usize{ config.hidden_dim, config.vocab_size };
        const proj_bound = math.sqrt(6.0 / @as(f32, @floatFromInt(config.hidden_dim + config.vocab_size)));
        var output_projection = try Tensor.randomUniform(allocator, &proj_shape, proj_bound, proj_bound, 137);
        errdefer output_projection.deinit();

        return JAIDEModel{
            .config = config,
            .tokenizer = tokenizer,
            .processor = processor,
            .index = index,
            .ranker = ranker,
            .sfd_optimizer = sfd_optimizer,
            .embedding_table = embedding_table,
            .output_projection = output_projection,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: JAIDEModel) void {
        self.embedding_table.deinit();
        self.output_projection.deinit();
        self.sfd_optimizer.deinit();
        self.ranker.deinit();
        self.index.deinit();
        self.tokenizer.deinit();
        self.processor.deinit();
    }

    pub fn forward(self: JAIDEModel, input_tokens: []const u32) !Tensor {
        const seq_len = input_tokens.len;
        if (seq_len == 0) return error.EmptyInput;

        const dim = self.config.hidden_dim;

        var embedded = try Tensor.zeros(self.allocator, &[_]usize{ seq_len, dim });
        errdefer embedded.deinit();

        for (input_tokens, 0..) |token_id, t| {
            const idx = @min(token_id, @as(u32, @intCast(self.config.vocab_size  1)));
            var d: usize = 0;
            while (d < dim) : (d += 1) {
                embedded.data[t  dim + d] = self.embedding_table.data[@as(usize, idx)  dim + d];
            }
        }

        var t: usize = 0;
        while (t < seq_len) : (t += 1) {
            var d: usize = 0;
            while (d < dim) : (d += 1) {
                const pos_f = @as(f32, @floatFromInt(t));
                const dim_f = @as(f32, @floatFromInt(d));
                const dim_total = @as(f32, @floatFromInt(dim));
                const angle = pos_f / math.pow(f32, 10000.0, 2.0  dim_f / dim_total);
                if (d % 2 == 0) {
                    embedded.data[t  dim + d] += @sin(angle);
                } else {
                    embedded.data[t  dim + d] += @cos(angle);
                }
            }
        }

        const rsf_dim = dim / 2;
        var rsf_input = try Tensor.zeros(self.allocator, &[_]usize{ seq_len, rsf_dim  2 });
        defer rsf_input.deinit();

        const copy_dim = @min(dim, rsf_dim  2);
        var s: usize = 0;
        while (s < seq_len) : (s += 1) {
            var d: usize = 0;
            while (d < copy_dim) : (d += 1) {
                rsf_input.data[s  rsf_dim  2 + d] = embedded.data[s  dim + d];
            }
        }

        try self.processor.forward(&rsf_input);

        var hidden = try Tensor.zeros(self.allocator, &[_]usize{ seq_len, dim });
        defer hidden.deinit();

        s = 0;
        while (s < seq_len) : (s += 1) {
            var d: usize = 0;
            while (d < copy_dim) : (d += 1) {
                hidden.data[s  dim + d] = rsf_input.data[s  rsf_dim  2 + d];
            }
        }

        const vocab = self.config.vocab_size;
        var logits = try Tensor.zeros(self.allocator, &[_]usize{ seq_len, vocab });
        embedded.deinit();

        s = 0;
        while (s < seq_len) : (s += 1) {
            var v: usize = 0;
            while (v < vocab) : (v += 1) {
                var dot: f32 = 0.0;
                var d: usize = 0;
                while (d < dim) : (d += 1) {
                    dot += hidden.data[s  dim + d]  self.output_projection.data[d  vocab + v];
                }
                logits.data[s  vocab + v] = dot;
            }
        }

        return logits;
    }

    pub fn inference(self: JAIDEModel, text: []const u8) ![]u32 {
        var token_list = std.ArrayList(u32).init(self.allocator);
        defer token_list.deinit();

        try self.tokenizer.encode(text, &token_list);

        if (token_list.items.len == 0) return error.EmptyInput;

        var logits = try self.forward(token_list.items);
        defer logits.deinit();

        const seq_len = token_list.items.len;
        const vocab = self.config.vocab_size;

        var output_tokens = try self.allocator.alloc(u32, seq_len);
        errdefer self.allocator.free(output_tokens);

        var s: usize = 0;
        while (s < seq_len) : (s += 1) {
            var best_idx: u32 = 0;
            var best_val: f32 = logits.data[s  vocab];
            var v: usize = 1;
            while (v < vocab) : (v += 1) {
                const val = logits.data[s  vocab + v];
                if (val > best_val) {
                    best_val = val;
                    best_idx = @intCast(v);
                }
            }
            output_tokens[s] = best_idx;
        }

        return output_tokens;
    }

    pub fn trainStep(self: JAIDEModel, input_tokens: []const u32, target_tokens: []const u32) !f32 {
        if (input_tokens.len != target_tokens.len) return error.ShapeMismatch;
        if (input_tokens.len == 0) return error.EmptyInput;

        const seq_len = input_tokens.len;
        const vocab = self.config.vocab_size;
        const dim = self.config.hidden_dim;

        var logits = try self.forward(input_tokens);
        defer logits.deinit();

        var loss: f32 = 0.0;
        var s: usize = 0;
        while (s < seq_len) : (s += 1) {
            var max_logit: f32 = logits.data[s  vocab];
            var v: usize = 1;
            while (v < vocab) : (v += 1) {
                const val = logits.data[s  vocab + v];
                if (val > max_logit) max_logit = val;
            }

            var log_sum_exp: f32 = 0.0;
            v = 0;
            while (v < vocab) : (v += 1) {
                log_sum_exp += @exp(logits.data[s  vocab + v]  max_logit);
            }
            log_sum_exp = max_logit + @log(log_sum_exp);

            const target_idx = @min(target_tokens[s], @as(u32, @intCast(vocab  1)));
            const target_logit = logits.data[s  vocab + @as(usize, target_idx)];
            loss += (target_logit  log_sum_exp);
        }
        loss /= @as(f32, @floatFromInt(seq_len));

        var grad_logits = try Tensor.zeros(self.allocator, &[_]usize{ seq_len, vocab });
        defer grad_logits.deinit();

        s = 0;
        while (s < seq_len) : (s += 1) {
            var max_logit: f32 = logits.data[s  vocab];
            var v: usize = 1;
            while (v < vocab) : (v += 1) {
                const val = logits.data[s  vocab + v];
                if (val > max_logit) max_logit = val;
            }

            var sum_exp: f32 = 0.0;
            v = 0;
            while (v < vocab) : (v += 1) {
                const e = @exp(logits.data[s  vocab + v]  max_logit);
                grad_logits.data[s  vocab + v] = e;
                sum_exp += e;
            }

            v = 0;
            while (v < vocab) : (v += 1) {
                grad_logits.data[s  vocab + v] /= sum_exp;
            }

            const target_idx = @min(target_tokens[s], @as(u32, @intCast(vocab  1)));
            grad_logits.data[s  vocab + @as(usize, target_idx)] = 1.0;

            v = 0;
            while (v < vocab) : (v += 1) {
                grad_logits.data[s  vocab + v] /= @as(f32, @floatFromInt(seq_len));
            }
        }

        var hidden = try Tensor.zeros(self.allocator, &[_]usize{ seq_len, dim });
        defer hidden.deinit();

        const rsf_dim = dim / 2;
        var rsf_input_recompute = try Tensor.zeros(self.allocator, &[_]usize{ seq_len, rsf_dim  2 });
        defer rsf_input_recompute.deinit();

        var t: usize = 0;
        while (t < seq_len) : (t += 1) {
            const idx = @min(input_tokens[t], @as(u32, @intCast(self.config.vocab_size  1)));
            var d: usize = 0;
            while (d < dim) : (d += 1) {
                hidden.data[t  dim + d] = self.embedding_table.data[@as(usize, idx)  dim + d];
            }
        }

        const copy_dim = @min(dim, rsf_dim  2);
        t = 0;
        while (t < seq_len) : (t += 1) {
            var d: usize = 0;
            while (d < copy_dim) : (d += 1) {
                rsf_input_recompute.data[t  rsf_dim  2 + d] = hidden.data[t  dim + d];
            }
        }

        try self.processor.forward(&rsf_input_recompute);

        t = 0;
        while (t < seq_len) : (t += 1) {
            var d: usize = 0;
            while (d < copy_dim) : (d += 1) {
                hidden.data[t  dim + d] = rsf_input_recompute.data[t  rsf_dim  2 + d];
            }
        }

        var proj_grad_flat = try self.allocator.alloc(f32, dim  vocab);
        defer self.allocator.free(proj_grad_flat);
        @memset(proj_grad_flat, 0.0);

        s = 0;
        while (s < seq_len) : (s += 1) {
            var d: usize = 0;
            while (d < dim) : (d += 1) {
                var v: usize = 0;
                while (v < vocab) : (v += 1) {
                    proj_grad_flat[d  vocab + v] += hidden.data[s  dim + d]  grad_logits.data[s  vocab + v];
                }
            }
        }

        const embed_param_count = self.config.vocab_size  dim;
        const proj_param_count = dim  vocab;
        const total_params = embed_param_count + proj_param_count;

        var all_grads = try SFDTensor.init(self.allocator, &[_]usize{total_params});
        defer all_grads.deinit();
        try all_grads.fill(0.0);

        var gi: usize = 0;
        while (gi < proj_param_count) : (gi += 1) {
            all_grads.data[embed_param_count + gi] = proj_grad_flat[gi];
        }

        var all_params = try SFDTensor.init(self.allocator, &[_]usize{total_params});
        defer all_params.deinit();

        gi = 0;
        while (gi < embed_param_count) : (gi += 1) {
            all_params.data[gi] = self.embedding_table.data[gi];
        }
        gi = 0;
        while (gi < proj_param_count) : (gi += 1) {
            all_params.data[embed_param_count + gi] = self.output_projection.data[gi];
        }

        try self.sfd_optimizer.update(&all_grads, &all_params, self.config.learning_rate);

        gi = 0;
        while (gi < embed_param_count) : (gi += 1) {
            self.embedding_table.data[gi] = all_params.data[gi];
        }
        gi = 0;
        while (gi < proj_param_count) : (gi += 1) {
            self.output_projection.data[gi] = all_params.data[embed_param_count + gi];
        }

        return loss;
    }

    pub fn generate(self: JAIDEModel, prompt: []const u8, max_tokens: u32) ![]u8 {
        var token_list = std.ArrayList(u32).init(self.allocator);
        defer token_list.deinit();

        try self.tokenizer.encode(prompt, &token_list);

        if (token_list.items.len == 0) {
            try token_list.append(MGT.SPECIAL_TOKENS.BOS);
        }

        var prng = PRNG.init(0xCAFEBABE);
        const temperature = self.config.temperature;
        const vocab = self.config.vocab_size;

        var generated: u32 = 0;
        while (generated < max_tokens) : (generated += 1) {
            const ctx_len = @min(token_list.items.len, self.config.max_seq_len);
            const ctx_start = token_list.items.len  ctx_len;
            const context = token_list.items[ctx_start..];

            var logits = try self.forward(context);
            defer logits.deinit();

            const last_pos = ctx_len  1;
            const logit_offset = last_pos  vocab;

            var max_logit: f32 = logits.data[logit_offset];
            var v: usize = 1;
            while (v < vocab) : (v += 1) {
                const val = logits.data[logit_offset + v];
                if (val > max_logit) max_logit = val;
            }

            var probs = try self.allocator.alloc(f32, vocab);
            defer self.allocator.free(probs);

            var sum_prob: f32 = 0.0;
            v = 0;
            while (v < vocab) : (v += 1) {
                const scaled = (logits.data[logit_offset + v]  max_logit) / temperature;
                probs[v] = @exp(scaled);
                sum_prob += probs[v];
            }

            if (sum_prob > 0.0) {
                v = 0;
                while (v < vocab) : (v += 1) {
                    probs[v] /= sum_prob;
                }
            }

            const rand_val = prng.float();
            var cumulative: f32 = 0.0;
            var sampled_token: u32 = 0;
            v = 0;
            while (v < vocab) : (v += 1) {
                cumulative += probs[v];
                if (cumulative >= rand_val) {
                    sampled_token = @intCast(v);
                    break;
                }
            }

            if (sampled_token == MGT.SPECIAL_TOKENS.EOS) break;

            try token_list.append(sampled_token);
        }

        var out_text = std.ArrayList(u8).init(self.allocator);
        errdefer out_text.deinit();

        try self.tokenizer.decode(token_list.items, &out_text);

        return try out_text.toOwnedSlice();
    }

    pub fn retrieve(self: JAIDEModel, query: []const u8, top_k: usize) ![]const u8 {
        var query_tokens = std.ArrayList(u32).init(self.allocator);
        defer query_tokens.deinit();

        try self.tokenizer.encode(query, &query_tokens);

        if (query_tokens.items.len == 0) return error.EmptyInput;

        var query_slice = try self.allocator.dupe(u32, query_tokens.items);
        defer self.allocator.free(query_slice);

        var candidates = try self.index.retrieveTopK(query_slice, top_k  10, self.allocator);
        defer {
            for (candidates) |c| {
                c.deinit(self.allocator);
            }
            self.allocator.free(candidates);
        }

        if (candidates.len > 0) {
            try self.ranker.rankCandidatesWithQuery(candidates, query_tokens.items, &self.index, self.allocator);
        }

        var result_text = std.ArrayList(u8).init(self.allocator);
        errdefer result_text.deinit();

        const result_count = @min(top_k, candidates.len);
        var i: usize = 0;
        while (i < result_count) : (i += 1) {
            if (i > 0) try result_text.appendSlice("\\n\\n");
            try self.tokenizer.decode(candidates[i].tokens, &result_text);
        }

        return try result_text.toOwnedSlice();
    }

    pub fn save(self: JAIDEModel, path: []const u8) !void {
        var tmp_buf: [512]u8 = undefined;
        const tmp_path = try std.fmt.bufPrint(&tmp_buf, "{s}.tmp", .{path});

        var file = try std.fs.cwd().createFile(tmp_path, .{ .mode = 0o600 });
        defer file.close();

        var buffered = std.io.bufferedWriter(file.writer());
        const w = buffered.writer();

        try w.writeAll("JAIDE001");

        try w.writeInt(u64, @intCast(self.config.hidden_dim), .little);
        try w.writeInt(u64, @intCast(self.config.num_layers), .little);
        try w.writeInt(u64, @intCast(self.config.num_heads), .little);
        try w.writeInt(u64, @intCast(self.config.fractal_depth), .little);
        try w.writeInt(u64, @intCast(self.config.vocab_size), .little);
        try w.writeInt(u64, @intCast(self.config.max_seq_len), .little);
        try w.writeInt(u32, @as(u32, @bitCast(self.config.learning_rate)), .little);
        try w.writeInt(u32, @as(u32, @bitCast(self.config.fisher_decay)), .little);
        try w.writeInt(u32, @as(u32, @bitCast(self.config.surprise_threshold)), .little);
        try w.writeInt(u32, @as(u32, @bitCast(self.config.momentum)), .little);
        try w.writeInt(u32, @as(u32, @bitCast(self.config.dropout_rate)), .little);
        try w.writeInt(u32, @as(u32, @bitCast(self.config.temperature)), .little);

        try self.embedding_table.save(w);
        try self.output_projection.save(w);

        try buffered.flush();
        try file.sync();

        try std.fs.cwd().rename(tmp_path, path);
    }

    pub fn load(allocator: Allocator, path: []const u8) !JAIDEModel {
        const file = try std.fs.cwd().openFile(path, .{ .mode = .read_only });
        defer file.close();

        var r = file.reader();

        var magic: [8]u8 = undefined;
        try r.readNoEof(&magic);
        if (!mem.eql(u8, &magic, "JAIDE001")) return error.BadFileFormat;

        var config = JAIDEConfig{};
        config.hidden_dim = @intCast(try r.readInt(u64, .little));
        config.num_layers = @intCast(try r.readInt(u64, .little));
        config.num_heads = @intCast(try r.readInt(u64, .little));
        config.fractal_depth = @intCast(try r.readInt(u64, .little));
        config.vocab_size = @intCast(try r.readInt(u64, .little));
        config.max_seq_len = @intCast(try r.readInt(u64, .little));
        config.learning_rate = @bitCast(try r.readInt(u32, .little));
        config.fisher_decay = @bitCast(try r.readInt(u32, .little));
        config.surprise_threshold = @bitCast(try r.readInt(u32, .little));
        config.momentum = @bitCast(try r.readInt(u32, .little));
        config.dropout_rate = @bitCast(try r.readInt(u32, .little));
        config.temperature = @bitCast(try r.readInt(u32, .little));

        var model = try JAIDEModel.init(allocator, config);
        errdefer model.deinit();

        model.embedding_table.deinit();
        model.embedding_table = try Tensor.load(allocator, r);

        model.output_projection.deinit();
        model.output_projection = try Tensor.load(allocator, r);

        return model;
    }

    pub fn parameterCount(self: const JAIDEModel) usize {
        const embed_params = self.config.vocab_size  self.config.hidden_dim;
        const proj_params = self.config.hidden_dim  self.config.vocab_size;

        const rsf_dim = self.config.hidden_dim / 2;
        const rsf_layer_params = rsf_dim  rsf_dim  2 + rsf_dim  2;
        const rsf_total = rsf_layer_params  self.config.num_layers;

        return embed_params + proj_params + rsf_total;
    }

    pub fn defaultConfig() JAIDEConfig {
        return JAIDEConfig{
            .hidden_dim = 512,
            .num_layers = 12,
            .num_heads = 8,
            .fractal_depth = 4,
            .vocab_size = 32000,
            .max_seq_len = 2048,
            .learning_rate = 1e4,
            .fisher_decay = 0.999,
            .surprise_threshold = 0.1,
            .momentum = 0.9,
            .ssi_max_height = 6,
            .ranker_num_ngrams = 64,
            .ranker_num_hash_funcs = 16,
            .ranker_seed = 0xDEADBEEF,
            .dropout_rate = 0.1,
            .temperature = 0.8,
            .clip_threshold = 1.0,
            .warmup_steps = 100,
        };
    }
};
